// The gatekeeper. No AI, no external service - just the booking rules.
// It answers one question: is this slot still free? Then it builds the invite.

const cfg = $('Booking settings').first().json;

// The Data Table lookup ran with "Always Output Data" on, so an empty result
// arrives as a single blank item. A row with a Date column means a real clash.
const clashes = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.Date === cfg.slotDate && r.Time === cfg.slotTime);

const available = clashes.length === 0;

if (!available) {
  return [{
    json: {
      available: false,
      slotDate: cfg.slotDate,
      slotTime: cfg.slotTime,
      title: 'That slot has just been taken',
      message: cfg.slotDate + ' at ' + cfg.slotTime + ' is already booked. Go back and pick another time.',
    },
  }];
}

// Build a real .ics invite. Times are written as local ("floating") times,
// so they land at the wall-clock time the visitor picked.
const pad = (n) => String(n).padStart(2, '0');
const [h, m] = cfg.slotTime.split(':').map(Number);
const start = new Date(cfg.slotDate + 'T' + pad(h) + ':' + pad(m) + ':00');
const end = new Date(start.getTime() + Number(cfg.meetingMinutes) * 60000);
const stamp = (d) =>
  d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) +
  'T' + pad(d.getHours()) + pad(d.getMinutes()) + '00';

// Fold and escape per RFC 5545 so the file opens cleanly in real calendars.
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');

const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//n8n//Booking Page//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  'UID:' + cfg.slotDate.replace(/-/g, '') + '-' + cfg.slotTime.replace(':', '') + '-' + Date.now() + '@booking.n8n',
  'DTSTAMP:' + stamp(new Date()) + 'Z',
  'DTSTART:' + stamp(start),
  'DTEND:' + stamp(end),
  'SUMMARY:' + esc(cfg.meetingSubject + ' - ' + cfg.attendeeName),
  'DESCRIPTION:' + esc('Booked through the n8n booking form.'),
  'ORGANIZER;CN=' + esc(cfg.organizerName) + ':mailto:' + cfg.organizerEmail,
  'ATTENDEE;CN=' + esc(cfg.attendeeName) + ';RSVP=TRUE:mailto:' + cfg.attendeeEmail,
  'STATUS:CONFIRMED',
  'END:VEVENT',
  'END:VCALENDAR',
].join('\r\n');

return [{
  json: {
    available: true,
    slotDate: cfg.slotDate,
    slotTime: cfg.slotTime,
    attendeeName: cfg.attendeeName,
    attendeeEmail: cfg.attendeeEmail,
    bookedAt: new Date().toISOString(),
    ics,
    title: 'Booked: ' + cfg.slotDate + ' at ' + cfg.slotTime,
    message: 'You are on the calendar, ' + cfg.attendeeName + '. The invite is attached to this execution as invite.ics.',
  },
}];
